#include <iostream>
#include <string>
#include <stdexcept>
#include <iomanip>

class Employee {
public:
    Employee(std::string first, std::string last, std::string ssn)
        : firstName(std::move(first)), lastName(std::move(last)), socialSecurityNumber(std::move(ssn)) {}
    virtual ~Employee() = default;
    virtual double earnings() const = 0;
    virtual void print() const {
        std::cout << firstName << " " << lastName << "\nsocial security number: " << socialSecurityNumber;
    }
private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
};

class CommissionEmployee : public Employee {
public:
    CommissionEmployee(std::string first, std::string last, std::string ssn, double sales, double rate)
        : Employee(std::move(first), std::move(last), std::move(ssn)) {
        setGrossSales(sales);
        setCommissionRate(rate);
    }
    void setGrossSales(double sales) {
        if (sales < 0.0) throw std::invalid_argument("Gross sales must be >= 0.0");
        grossSales = sales;
    }
    void setCommissionRate(double rate) {
        if (rate <= 0.0 || rate >= 1.0) throw std::invalid_argument("Commission rate must be > 0.0 and < 1.0");
        commissionRate = rate;
    }
    double getGrossSales() const { return grossSales; }
    double getCommissionRate() const { return commissionRate; }
    double earnings() const override { return getGrossSales() * getCommissionRate(); }
    void print() const override {
        std::cout << "commission employee: ";
        Employee::print();
        std::cout << "\ngross sales: " << getGrossSales() << "; commission rate: " << getCommissionRate();
    }
private:
    double grossSales{0.0};
    double commissionRate{0.0};
};

class BasePlusCommissionEmployee : public CommissionEmployee {
public:
    BasePlusCommissionEmployee(std::string first, std::string last, std::string ssn,
                               double sales, double rate, double salary)
        : CommissionEmployee(std::move(first), std::move(last), std::move(ssn), sales, rate) {
        setBaseSalary(salary);
    }
    void setBaseSalary(double salary) {
        if (salary < 0.0) throw std::invalid_argument("Salary must be >= 0.0");
        baseSalary = salary;
    }
    double getBaseSalary() const { return baseSalary; }
    double earnings() const override {
        return getBaseSalary() + CommissionEmployee::earnings();
    }
    void print() const override {
        std::cout << "base-salaried ";
        CommissionEmployee::print();
        std::cout << "; base salary: " << getBaseSalary();
    }
private:
    double baseSalary{0.0};
};

int main() {
    std::cout << std::fixed << std::setprecision(2);
    BasePlusCommissionEmployee emp("Bob", "Lewis", "444-44-4444", 5000.0, 0.04, 300.0);
    emp.print();
    std::cout << "\nearned $" << emp.earnings() << "\n";
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <memory>
#include <iomanip>

class Employee {
public:
    Employee(std::string first, std::string last, std::string ssn)
        : firstName(std::move(first)), lastName(std::move(last)), socialSecurityNumber(std::move(ssn)) {}
    virtual ~Employee() = default;
    virtual double earnings() const = 0;
    virtual void print() const {
        std::cout << firstName << " " << lastName << "\nsocial security number: " << socialSecurityNumber;
    }
private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
};

class SalariedEmployee : public Employee {
public:
    SalariedEmployee(std::string first, std::string last, std::string ssn, double salary)
        : Employee(std::move(first), std::move(last), std::move(ssn)), weeklySalary(salary) {}
    double earnings() const override { return weeklySalary; }
    void print() const override {
        std::cout << "salaried employee: ";
        Employee::print();
        std::cout << "\nweekly salary: " << weeklySalary;
    }
private:
    double weeklySalary{0.0};
};

class CommissionEmployee : public Employee {
public:
    CommissionEmployee(std::string first, std::string last, std::string ssn, double sales, double rate)
        : Employee(std::move(first), std::move(last), std::move(ssn)), grossSales(sales), commissionRate(rate) {}
    double earnings() const override { return grossSales * commissionRate; }
    void print() const override {
        std::cout << "commission employee: ";
        Employee::print();
        std::cout << "\ngross sales: " << grossSales << "; commission rate: " << commissionRate;
    }
private:
    double grossSales{0.0};
    double commissionRate{0.0};
};

void virtualViaPointer(const Employee* const ptr) {
    ptr->print();
    std::cout << "\nearned $" << ptr->earnings() << "\n\n";
}

void virtualViaReference(const Employee& ref) {
    ref.print();
    std::cout << "\nearned $" << ref.earnings() << "\n\n";
}

int main() {
    std::cout << std::fixed << std::setprecision(2);

    SalariedEmployee salaried("John", "Smith", "111-11-1111", 800.0);
    CommissionEmployee commission("Sue", "Jones", "333-33-3333", 10000.0, 0.06);

    // Static binding
    std::cout << "--- Static Binding ---\n";
    salaried.print();
    std::cout << "\nearned $" << salaried.earnings() << "\n\n";

    // Dynamic binding via pointer vector
    std::cout << "--- Dynamic Binding (Pointer) ---\n";
    std::vector<const Employee*> employees{&salaried, &commission};
    for (const Employee* empPtr : employees) {
        virtualViaPointer(empPtr);
    }

    // Dynamic binding via reference
    std::cout << "--- Dynamic Binding (Reference) ---\n";
    for (const Employee* empPtr : employees) {
        virtualViaReference(*empPtr);
    }

    return 0;
}
